-- Rollback-only hosted test: no test programs, timetable changes, memberships or results persist.
begin;
do $$
declare aid uuid; uid uuid; eid text; slot uuid:=gen_random_uuid(); ws date; tidrev int; wid uuid; cid uuid; pid uuid; livecid uuid; payload jsonb; movement jsonb; result jsonb; p jsonb; wall jsonb; screen jsonb;
begin
 select id into aid from public.profiles where role in ('owner','admin') order by id limit 1;
 select id into uid from public.profiles where role='member' order by id limit 1;
 ws:=date_trunc('week',now() at time zone 'Asia/Seoul')::date+28;
 while exists(select 1 from public.group_weeks where week_start=ws and status<>'archived') loop ws:=ws+7;end loop;
 perform set_config('request.jwt.claim.sub',aid::text,true);perform set_config('role','authenticated',true);
 perform public.group_set_member(uid,true);
 eid:=public.group_add_exercise('ROLLBACK STRENGTH');
 movement:=jsonb_build_object('id','strength','exercise_id',eid,'label','Back SQ test','kind','weight','training_type','strength','target_reps',10,'unit','kg','load_basis','total','load_step',2.5,'min_load',20,'sets','[{"reps":10,"rir":3},{"reps":10,"rir":3},{"reps":8,"rir":3},{"reps":8,"rir":3},{"reps":8,"rir":3}]'::jsonb);
 select revision into tidrev from public.group_timetable where id;
 perform public.group_save_timetable(jsonb_build_array(jsonb_build_object('id',slot,'dow',1,'time','18:00','duration_minutes',50,'coach_id',aid)),tidrev);
 payload:=jsonb_build_object('week_start',ws,'title','ROLLBACK WEEK','status','published','days',jsonb_build_array(jsonb_build_object('dow',1,'title','ROLLBACK DAY','description','test','movements',jsonb_build_array(movement))));
 result:=public.group_save_week(payload);wid:=(result->>'id')::uuid;
 if (result->>'created')::int<>1 then raise exception 'Weekly class not generated';end if;
 select id into cid from public.group_classes where week_id=wid;
 perform public.group_join(cid,array[uid]);
 p:=public.group_detail(cid)->'participants'->0;
 if p->>'status'<>'planned' then raise exception 'Future roster incorrectly started';end if;
 result:=public.group_save_week(payload||jsonb_build_object('id',wid,'revision',1));
 if (result->>'created')::int<>0 or (result->>'kept')::int<>1 then raise exception 'Idempotency or frozen roster failure';end if;
 perform set_config('request.jwt.claim.sub',uid::text,true);
 if not exists(select 1 from public.group_weeks where id=wid) then raise exception 'Member cannot read weekly program';end if;
 begin perform public.group_join(cid);raise exception 'Future self-start permitted';exception when raise_exception then if SQLERRM not like '오늘 참가%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',aid::text,true);
 perform public.group_set_strength_max(jsonb_build_object('user_id',uid,'exercise_id',eid,'unit','kg','load_basis','total','weight',100,'measured_on',(now() at time zone 'Asia/Seoul')::date,'basis','measured','reason','ROLLBACK'));
 livecid:=public.group_save_class(jsonb_build_object('title','ROLLBACK STRENGTH LIVE','starts_at',((now() at time zone 'Asia/Seoul')::date+time '00:00') at time zone 'Asia/Seoul','duration_minutes',50,'coach_id',aid,'movements',jsonb_build_array(movement)));
 perform public.group_set_class_status(livecid,'published',1);perform public.group_set_class_status(livecid,'open',2);
 perform set_config('request.jwt.claim.sub',uid::text,true);perform public.group_join(livecid);perform public.group_set_privacy('ROLLBACK SETS',true);
 p:=public.group_detail(livecid)->'participants'->0;pid:=(p->>'id')::uuid;
 if (p->'recommendations'->'strength'->'sets'->0->>'weight')::numeric<>67.5 or (p->'recommendations'->'strength'->'sets'->2->>'weight')::numeric<>72.5 then raise exception '1RM set recommendation mismatch';end if;
 begin perform public.group_save_participant(pid,1,'{"status":"completed"}');raise exception 'Missing final RPE allowed';exception when raise_exception then if SQLERRM not like '마지막으로%' then raise;end if;end;
 perform public.group_save_participant(pid,1,'{"status":"completed","session_rpe":7,"results":{"strength":{"sets":[{"weight":67.5,"reps":10,"rir":3},{},{},{},{}]}}}');
 perform set_config('request.jwt.claim.sub',aid::text,true);
 wall:=public.group_create_wall('ROLLBACK SET TV');perform public.group_control_wall((wall->>'id')::uuid,livecid,'strength');
 perform set_config('request.jwt.claim.sub','',true);perform set_config('role','anon',true);
 screen:=public.group_display(wall->>'recommendations');
 if jsonb_array_length(screen->'participants'->0->'recommendations'->'strength'->'sets')<>5 or screen::text like '%source_id%' or screen::text like '%session_rpe%' then raise exception 'TV set projection mismatch';end if;
 perform set_config('role','authenticated',true);perform set_config('request.jwt.claim.sub',aid::text,true);
 perform public.group_set_class_status(livecid,'ended',3);perform public.group_remove_program('class',livecid,4);perform public.group_remove_program('week',wid,2);
 perform set_config('request.jwt.claim.sub',uid::text,true);
 p:=public.group_detail(livecid)->'participants'->0;
 if p->>'status'<>'completed' or (p->>'session_rpe')::numeric<>7 or jsonb_array_length(p->'results'->'strength'->'sets')<>5 then raise exception 'Deletion damaged history';end if;
 perform set_config('role','none',true);
end $$;
rollback;
select 'PASS: hosted weekly publication, planned roster, 1RM set suggestions, member RPE, TV projection, archive/history; all test changes rolled back' as result;
